; C64 Math Library: optional compact_opt ATAN2 kernel, WITH all required tables.
; GENERATED by routines/atan2/export_optimized.py; edit the canonical source.
; Assemble: acme -f cbm -o atan2.prg atan2_s8_s8_u8_compact_opt.asm
; Load the PRG, bank RAM in as necessary, and JSR atan2_s8_s8_u8.
; X0/Y0/Z0 are memory addresses, not CPU registers. Set D=0 before calling.
; No initialization, ZP, scratch, self-modifying code, or extra stack is needed.
; The only stack use is the caller's ordinary two-byte JSR return address.
; To relocate, edit ATAN2_CODE, PUBLIC_ENTRY, X0/Y0/Z0 and the table constants.
; Keep tables page aligned and all code/data/I/O/stack regions disjoint.
; Use page-aligned ATAN2_CODE for the published cycle counts.
; This standalone layout is NOT an overlay for the shipped resident profiles.
!cpu 6502
ATAN2_CODE = $8000
PUBLIC_ENTRY = $7F00
* = PUBLIC_ENTRY
atan2_s8_s8_u8:
    jmp atan2

; Optimized compact ATAN2. Same LOG/ATAN pages and outputs as atan2_compact.
; Inputs X0/Y0 are preserved; Z0 and A return phase; D=0 required, C=0 returned.
; No ZP, scratch, self-modification, or undocumented instructions.
; @ORG@ is replaced by the standalone benchmark/exporter.
X0=$C000
Y0=$C004
Z0=$C008
LOGTAB=$9600
ATANTAB=$9700
* = ATAN2_CODE
atan2:
    ldx X0
    beq axis
    sec
    bmi xneg
    lda LOGTAB,x
    ldx Y0
    bmi xpyn
    sbc LOGTAB,x
    tax
    lda ATANTAB,x
    sta Z0
    clc
    rts
xpyn:
    sbc LOGTAB,x
    tax
    lda #$00
    sec
    sbc ATANTAB,x
    sta Z0
    clc
    rts
xneg:
    lda LOGTAB,x
    ldx Y0
    bmi xnyn
    sbc LOGTAB,x
    tax
    lda #$80
    sec
    sbc ATANTAB,x
    sta Z0
    clc
    rts
xnyn:
    sbc LOGTAB,x
    tax
    lda ATANTAB,x
    eor #$80
    sta Z0
    clc
    rts
axis:
    clc
    lda Y0
    beq axis_store
    asl
    lda #$80
    ror
axis_store:
    sta Z0
    rts

